/**
 * The page's fonts (D-083), inside the binary so the page stays offline and
 * CDN-free: Electrolize for English, IBM Plex Sans Thai for Thai (and for the
 * punctuation Electrolize lacks). Both SIL Open Font License 1.1 — the
 * licences are beside this file in fonts/. woff2 subsets from @fontsource v5.
 * Served at /fonts/<name>.woff2 by the web server.
 */

export const FONT_FILES: Readonly<Record<string, string>> = {
  "electrolize-latin-400": "",
  "plex-thai-thai-400": "",
  "plex-thai-thai-600": "",
  "plex-thai-latin-400": "",
  "plex-thai-latin-600": "",
};

/** The bytes of one font, or `undefined` for a name that is not one. */
export function fontBytes(name: string): Uint8Array | undefined {
  const b64 = Object.hasOwn(FONT_FILES, name) ? FONT_FILES[name] : undefined;
  return b64 === undefined ? undefined : Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
}

const THAI = "U+02D7,U+0303,U+0331,U+0E01-0E5B,U+200C-200D,U+25CC";
const LATIN = "U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD";

const face = (family: string, file: string, weight: number, range: string) =>
  `@font-face{font-family:"${family}";font-style:normal;font-weight:${weight};font-display:swap;src:url(/fonts/${file}.woff2) format("woff2");unicode-range:${range}}`;

export const FONT_CSS = [
  face("Electrolize", "electrolize-latin-400", 400, LATIN),
  face("IBM Plex Sans Thai", "plex-thai-thai-400", 400, THAI),
  face("IBM Plex Sans Thai", "plex-thai-thai-600", 600, THAI),
  face("IBM Plex Sans Thai", "plex-thai-latin-400", 400, LATIN),
  face("IBM Plex Sans Thai", "plex-thai-latin-600", 600, LATIN),
].join("\n");

export const FONT_STACK = `"Electrolize","IBM Plex Sans Thai",ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif`;
